def visit_failure[T](failure: OperationFailure, visitor: FailureVisitor[T]) -> T:
    match failure.category:
        case FailureCategory.INVALID_INPUT:
            return visitor.invalid_input(failure)
        case FailureCategory.CONFIGURATION:
            return visitor.configuration(failure)
        case FailureCategory.CONFLICT:
            return visitor.conflict(failure)
        case FailureCategory.NOT_FOUND:
            return visitor.not_found(failure)
        case FailureCategory.PERMISSION_DENIED:
            return visitor.permission_denied(failure)
        case FailureCategory.UNSUPPORTED:
            return visitor.unsupported(failure)
        case FailureCategory.RESOURCE_EXHAUSTED:
            return visitor.resource_exhausted(failure)
        case FailureCategory.TRANSIENT:
            return visitor.transient(failure)
        case FailureCategory.CANCELLED:
            return visitor.cancelled(failure)
        case FailureCategory.DEADLINE_EXCEEDED:
            return visitor.deadline_exceeded(failure)
        case FailureCategory.ADMISSION_UNCONFIRMED:
            return visitor.admission_unconfirmed(failure)
        case FailureCategory.INTERNAL:
            return visitor.internal(failure)
        case _:
            raise ValueError("unknown failure category")


